import { type ElementType, type ReactNode, useEffect, useMemo, useState } from 'react';
import { Router as WouterRouter, useLocation } from 'wouter';
import { Activity, AlertOctagon, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, Box, Boxes, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Cloud, Command, Database, DollarSign, Download, ExternalLink, FileClock, FileText, Filter, GitBranch, Globe2, LayoutDashboard, ListFilter, LoaderCircle, LockKeyhole, MoreHorizontal, Moon, Network, Package, PanelLeftClose, PanelLeftOpen, Plus, Radio, RefreshCw, Search, Server, Settings2, Shield, ShieldAlert, ShieldCheck, SlidersHorizontal, Sun, TerminalSquare, Timer, Workflow, X, Zap } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis, BarChart, Bar } from 'recharts';
import { dataProvider } from '@/data/provider';
import type { Alert, AuditEvent, Change, CostRecord, Deployment, Environment, Incident, LogEntry, Metric, Runbook, Server as ServerRecord, Service, Trace } from '@/data/types';
import { alerts as initialAlerts, changes as initialChanges, deployments as initialDeployments, incidents as initialIncidents } from '@/data/fixtures';
import './index.css';
import './app.css';

type Data = { environments: Environment[]; services: Service[]; deployments: Deployment[]; incidents: Incident[]; alerts: Alert[]; servers: ServerRecord[]; metrics: Metric[]; logs: LogEntry[]; traces: Trace[]; changes: Change[]; runbooks: Runbook[]; costs: CostRecord[]; auditEvents: AuditEvent[] };
type Toast = { message: string; kind?: 'success' | 'warning' };
const navGroups: { label: string; items: [string, string, ElementType][] }[] = [
  { label:'OPERATIONS', items:[['/','Command Center',LayoutDashboard],['/deployments','Deployment Center',Package],['/release-history','Release history',Clock3],['/pipelines','Pipelines',Workflow],['/incidents','Incidents',AlertOctagon],['/alerts','Alert center',Bell],['/changes','Change management',FileClock],['/runbooks','Runbooks',FileText]] },
  { label:'PLATFORM', items:[['/services','Services',Boxes],['/service-catalog','Service catalog',Database],['/dependencies','Dependencies',Network],['/environments','Environments',Globe2],['/servers','Servers',Server],['/containers','Containers',Box],['/infrastructure','Infrastructure',Cloud]] },
  { label:'OBSERVABILITY', items:[['/metrics','Metrics',Activity],['/logs','Logs',TerminalSquare],['/traces','Traces',GitBranch],['/reliability','Reliability',ShieldCheck]] },
  { label:'GOVERNANCE', items:[['/cost','Cloud cost',DollarSign],['/optimization','Optimization',ArrowDownRight],['/security','Security',Shield],['/audit','Audit trail',FileText],['/engineering','Engineering',Zap],['/reports','Reports',ListFilter]] },
];
const pageMeta: Record<string,{title:string;eyebrow:string;description:string}> = {
  '/':{title:'Command Center',eyebrow:'OPERATIONS OVERVIEW',description:'Your operational picture, at a glance.'},
  '/deployments':{title:'Deployment Center',eyebrow:'DELIVERY',description:'Release activity across environments.'},
  '/release-history':{title:'Release history',eyebrow:'DELIVERY',description:'A complete timeline of changes reaching your services.'},
  '/pipelines':{title:'Pipeline runs',eyebrow:'DELIVERY',description:'Build, test, and promotion status for recent runs.'},
  '/services':{title:'Service catalog',eyebrow:'PLATFORM',description:'Ownership, health, and runtime context for every service.'},
  '/service-catalog':{title:'Catalog metadata',eyebrow:'PLATFORM',description:'Service ownership records and operational metadata.'},
  '/dependencies':{title:'Dependency map',eyebrow:'PLATFORM',description:'Understand the paths that connect services and customers.'},
  '/incidents':{title:'Incidents',eyebrow:'OPERATIONS',description:'Coordinate response, ownership, and customer impact.'},
  '/alerts':{title:'Alert center',eyebrow:'OPERATIONS',description:'Triage signals with context, not noise.'},
  '/runbooks':{title:'Runbook library',eyebrow:'OPERATIONS',description:'Practical response guidance maintained by service teams.'},
  '/changes':{title:'Change management',eyebrow:'OPERATIONS',description:'Review risk and coordinate planned production changes.'},
  '/environments':{title:'Environments',eyebrow:'PLATFORM',description:'Health and release posture from QA to production.'},
  '/servers':{title:'Infrastructure inventory',eyebrow:'PLATFORM',description:'Compute nodes and utilization across managed environments.'},
  '/containers':{title:'Container inventory',eyebrow:'PLATFORM',description:'Workload health and runtime distribution.'},
  '/infrastructure':{title:'Infrastructure map',eyebrow:'PLATFORM',description:'A connected view of workloads, networks, and data stores.'},
  '/metrics':{title:'Metrics explorer',eyebrow:'OBSERVABILITY',description:'Service-level signals over the selected time window.'},
  '/logs':{title:'Structured logs',eyebrow:'OBSERVABILITY',description:'Search and inspect recent application events.'},
  '/traces':{title:'Distributed traces',eyebrow:'OBSERVABILITY',description:'Follow requests across service boundaries.'},
  '/cost':{title:'Cloud cost',eyebrow:'FINOPS',description:'Spend trends, budgets, and service-level allocation.'},
  '/optimization':{title:'Optimization',eyebrow:'FINOPS',description:'Actionable opportunities to reduce waste without adding risk.'},
  '/security':{title:'Security posture',eyebrow:'GOVERNANCE',description:'Findings, policy status, and remediation ownership.'},
  '/audit':{title:'Audit trail',eyebrow:'GOVERNANCE',description:'A searchable timeline of platform actions.'},
  '/engineering':{title:'Engineering analytics',eyebrow:'ENGINEERING',description:'Delivery flow and operational performance signals.'},
  '/reliability':{title:'Reliability objectives',eyebrow:'RELIABILITY',description:'SLOs, SLIs, service-level commitments, and error budgets.'},
  '/reports':{title:'Operational reports',eyebrow:'GOVERNANCE',description:'Shareable snapshots of reliability, delivery, and cost.'},
};
const money = (n:number) => `$${n.toLocaleString('en-US',{maximumFractionDigits:0})}`;

function CommandCenter() {
  const [location,setLocation] = useLocation();
  const [data,setData] = useState<Data|null>(null);
  const [loading,setLoading] = useState(true);
  const [loadError,setLoadError] = useState(false);
  const [dark,setDark] = useState(localStorage.getItem('cloudops-theme') !== 'light');
  const [collapsed,setCollapsed] = useState(false);
  const [env,setEnv] = useState('ALL');
  const [serviceFilter,setServiceFilter] = useState('ALL SERVICES');
  const [workspace,setWorkspace] = useState('Northstar Engineering');
  const [period,setPeriod] = useState('24 hours');
  const [search,setSearch] = useState('');
  const [drawer,setDrawer] = useState<unknown|null>(null);
  const [palette,setPalette] = useState(false);
  const [notify,setNotify] = useState(false);
  const [profile,setProfile] = useState(false);
  const [createOpen,setCreateOpen] = useState(false);
  const [toast,setToast] = useState<Toast|null>(null);
  const [alertsState,setAlertsState] = useState(initialAlerts);
  const [incidentState,setIncidentState] = useState(initialIncidents);
  const [changeState,setChangeState] = useState(initialChanges);
  const [deploymentState,setDeploymentState] = useState(initialDeployments);
  const [filter,setFilter] = useState('All');
  const pathname = location || '/';
  const meta = pageMeta[pathname] ?? {title:'Service detail',eyebrow:'SERVICE CATALOG',description:'Ownership, dependencies, and runtime health.'};
  useEffect(()=>{ document.documentElement.classList.toggle('dark',dark); localStorage.setItem('cloudops-theme',dark?'dark':'light'); },[dark]);
  useEffect(()=>{ let alive=true; setLoading(true); setLoadError(false); Promise.all([dataProvider.getEnvironments(),dataProvider.getServices(),dataProvider.getDeployments(),dataProvider.getIncidents(),dataProvider.getAlerts(),dataProvider.getServers(),dataProvider.getMetrics(),dataProvider.getLogs(),dataProvider.getTraces(),dataProvider.getChanges(),dataProvider.getRunbooks(),dataProvider.getCosts(),dataProvider.getAuditEvents()]).then(([environments,services,deployments,incidents,alerts,servers,metrics,logs,traces,changes,runbooks,costs,auditEvents])=>{if(alive){setData({environments,services,deployments,incidents,alerts,servers,metrics,logs,traces,changes,runbooks,costs,auditEvents});setLoading(false)}}).catch(()=>{if(alive){setLoadError(true);setLoading(false)}}); return ()=>{alive=false}; },[]);
  useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setPalette(x=>!x)} if(e.key==='Escape'){setPalette(false);setDrawer(null);setCreateOpen(false);setNotify(false)}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(null),3200);return()=>clearTimeout(t)},[toast]);
  useEffect(()=>{const listener=(e:Event)=>setToast({message:(e as CustomEvent<string>).detail});window.addEventListener('cloudops-toast',listener);return()=>window.removeEventListener('cloudops-toast',listener)},[]);
  useEffect(()=>{const listener=(e:Event)=>setDrawer((e as CustomEvent<unknown>).detail);window.addEventListener('cloudops-security-detail',listener);return()=>window.removeEventListener('cloudops-security-detail',listener)},[]);
  const current = data;
  const visibleServices = useMemo(()=>current?.services.filter(s=>(env==='ALL'||s.environment===env)&&(serviceFilter==='ALL SERVICES'||s.name===serviceFilter))??[],[current,env,serviceFilter]);
  const go=(path:string)=>{setLocation(path);setSearch('');setDrawer(null)};
  const showToast=(message:string,kind:'success'|'warning'='success')=>setToast({message,kind});
  const acknowledge=(id:string)=>{setIncidentState(prev=>prev.map(i=>i.id===id?{...i,acknowledged:true}:i));showToast(`${id} acknowledged`);};
  const actAlert=(id:string,action:'Acknowledged'|'Resolved'|'Suppressed')=>{setAlertsState(prev=>prev.map(a=>a.id===id?{...a,status:action}:a));showToast(`Alert ${id} ${action.toLowerCase()}`)};
  const approve=(id:string)=>{const change=changeState.find(x=>x.id===id);if(!change)return;if(change.environment==='PRODUCTION'&&!window.confirm(`Simulate two-person approval for ${id}?\n\nRequested by: ${change.requester}\nApproving reviewer: Maya Patel\nRisk: ${change.risk}\n\nNo production deployment will run.`))return;setChangeState(prev=>prev.map(c=>c.id===id?{...c,status:'Approved',approvedBy:'Maya Patel',approvalTimestamp:new Date().toLocaleString(),riskAssessment:`${c.risk} risk reviewed; staged rollout and rollback criteria confirmed.`}:c));showToast(change.environment==='PRODUCTION'?`Production approval simulation recorded for ${id}`:`Change ${id} approved in ${change.environment}`)};
  const simulateDeploy=()=>{const targetEnvironment=env==='ALL'?'QA':env;if(targetEnvironment==='PRODUCTION'&&!window.confirm('Production deployment requires approval. Simulate approval by Maya Patel before queuing this demo deployment?\n\nRisk assessment: standard staged rollout with health checks.\nNo infrastructure action will run.'))return;const d:Deployment={id:`REL-${1100+deploymentState.length}`,service:serviceFilter==='ALL SERVICES'?'checkout-api':serviceFilter,environment:targetEnvironment,version:'v4.29.0',status:'Running',author:'You',time:'just now',duration:'starting',commit:'local-demo',branch:'main',pipeline:'CloudOps release pipeline',approvalStatus:targetEnvironment==='PRODUCTION'?'Approved · simulation':'Not required',requestedBy:'You',approvedBy:targetEnvironment==='PRODUCTION'?'Maya Patel':undefined,approvalTimestamp:targetEnvironment==='PRODUCTION'?new Date().toLocaleString():undefined,riskAssessment:targetEnvironment==='PRODUCTION'?'Standard staged rollout approved in local simulation.':undefined};setDeploymentState([d,...deploymentState]);showToast(targetEnvironment==='PRODUCTION'?'Production approval simulated; demo deployment queued':'Demo deployment queued in local simulation');};
  const createRecord=(name:string,title:string,serviceName:string,details:string)=>{setCreateOpen(false);if(name==='incident'){setIncidentState(prev=>[{id:`INC-${8500+prev.length}`,title:title||'New locally simulated incident',severity:'SEV-3',status:'Investigating',service:serviceName,environment:env==='ALL'?'QA':env,owner:'Maya Patel',started:'just now',acknowledged:false,impact:details||'Impact pending assessment',assignedEngineer:'Maya Patel',incidentCommander:'Maya Patel',affectedServices:[serviceName],timeline:[{time:'just now',event:'Incident created in the local demo workspace.'}]},...prev]);}if(name==='change request'){setChangeState(prev=>[{id:`CHG-${410+prev.length}`,title:title||'New locally simulated change',service:serviceName,environment:env==='ALL'?'QA':env,requester:'Maya Patel',status:'Pending',risk:'Low',window:'Next available window',description:details||'Created from the local demo workflow.'},...prev]);}if(name==='service'&&current){const nameSlug=title.replace(/[^a-z0-9-]/gi,'-').toLowerCase();const next:Service={id:`svc-${current.services.length+1}`,name:nameSlug,team:'Platform',tier:'Tier 2',health:'Healthy',environment:env==='ALL'?'QA':env,region:'us-east-1',version:'v0.1.0',dependencies:[],owner:'Maya Patel',slo:99.9,description:details||title,repository:`github.com/northstar/${nameSlug}`,language:'TypeScript',availability:99.9,latencyMs:0,errorRate:0,documentation:`/docs/services/${nameSlug}`,runbook:'RB-210',lastDeployment:'Not deployed',incidentCount:0,risk:'Low'};setData({...current,services:[next,...current.services]});}showToast(`${name} created in local demo state`);};
  const filteredAlerts=alertsState.filter(a=>(env==='ALL'||a.environment===env)&&(serviceFilter==='ALL SERVICES'||a.service===serviceFilter)&&(filter==='All'||a.severity===filter||a.status===filter)&&(a.title+a.service+a.id).toLowerCase().includes(search.toLowerCase()));
  const filteredIncidents=incidentState.filter(a=>(env==='ALL'||a.environment===env)&&(serviceFilter==='ALL SERVICES'||a.service===serviceFilter)&&(filter==='All'||a.severity===filter||a.status===filter)&&(a.title+a.service+a.id).toLowerCase().includes(search.toLowerCase()));
  const filteredDeployments=deploymentState.filter(d=>(env==='ALL'||d.environment===env)&&(serviceFilter==='ALL SERVICES'||d.service===serviceFilter));

  return <div className={`app-shell ${dark?'dark':''}`}>
    <aside className={`sidebar ${collapsed?'sidebar-collapsed':''}`}>
      <div className="brand"><div className="brand-mark"><Activity size={18}/></div>{!collapsed&&<div><div className="brand-name">CLOUDOPS</div><div className="brand-sub">COMMAND CENTER <span className="demo-dot"/> DEMO</div></div>}<button className="icon-button side-collapse" aria-label="Collapse navigation" onClick={()=>setCollapsed(!collapsed)}>{collapsed?<PanelLeftOpen size={16}/>:<PanelLeftClose size={16}/>}</button></div>
      <button className="workspace-switch" aria-label="Switch organization or project" onClick={()=>setWorkspace(current=>current==='Northstar Engineering'?'Commerce Platform':current==='Commerce Platform'?'Infrastructure':'Northstar Engineering')}><div className="workspace-icon">{workspace.charAt(0)}</div>{!collapsed&&<><span>{workspace}</span><ChevronDown size={14}/></>}</button>
      <nav className="nav-scroll">{navGroups.map(group=><div className="nav-group" key={group.label}><div className="nav-label">{!collapsed?group.label:'·'}</div>{group.items.map(([path,label,Icon])=><button key={path} className={`nav-item ${pathname===path?'nav-active':''}`} title={label} onClick={()=>go(path)}><Icon size={16}/>{!collapsed&&<span>{label}</span>}{!collapsed&&path==='/incidents'&&<span className="nav-count">3</span>}</button>)}</div>)}</nav>
      {!collapsed&&<div className="sidebar-bottom"><div className="demo-badge"><span className="pulse-dot"/> Demo data only</div><button className="nav-item" onClick={()=>showToast('Settings are available in this local preview.')}><Settings2 size={16}/><span>Workspace settings</span></button><div className="sidebar-build"><span>Command Center</span><span className="mono">v0.9.4</span></div></div>}
    </aside>
    <main className="main-shell">
      <header className="topbar"><div className="crumb"><span className="crumb-root">CloudOps</span><span className="crumb-slash">/</span><span>{meta.title}</span></div><div className="top-actions">
        <label className="env-select service-select"><Boxes size={14}/><select value={serviceFilter} aria-label="Service selector" onChange={e=>setServiceFilter(e.target.value)}><option>ALL SERVICES</option>{data?.services.map(s=><option key={s.id} value={s.name}>{s.name}</option>)}</select><ChevronDown size={12}/></label>
        <label className={`env-select ${env==='PRODUCTION'?'env-production':''}`}><Globe2 size={14}/><select value={env} aria-label="Environment selector" onChange={e=>setEnv(e.target.value)}><option value="ALL">ALL ENVIRONMENTS</option><option value="QA">QA</option><option value="UAT">UAT</option><option value="PRODUCTION">PRODUCTION</option></select><ChevronDown size={12}/></label>
        <label className="env-select range-select"><Clock3 size={14}/><select aria-label="Date and time range" value={period} onChange={e=>setPeriod(e.target.value)}><option>1 hour</option><option>24 hours</option><option>7 days</option><option>30 days</option></select><ChevronDown size={12}/></label>
        <button className="search-trigger" onClick={()=>setPalette(true)}><Search size={14}/><span>Search anything</span><kbd><Command size={10}/> K</kbd></button>
        <button className="icon-button theme-toggle" aria-label="Toggle color theme" onClick={()=>setDark(!dark)}>{dark?<Sun size={16}/>:<Moon size={16}/>}</button>
        <div className="pop-anchor"><button className="icon-button notification-button" aria-label="Open notifications" onClick={()=>{setNotify(!notify);setProfile(false)}}><Bell size={16}/><i/></button>{notify&&<div className="popover-card notification-pop"><div className="popover-title">Notifications <span className="tiny-tag">3 NEW</span></div>{incidentState.filter(x=>!x.acknowledged).slice(0,3).map(i=><button className="notification-row" key={i.id} onClick={()=>{setNotify(false);go('/incidents');setDrawer(i)}}><span className="severity-dot red"/><span><b>{i.title}</b><small>{i.id} · {i.started}</small></span></button>)}<button className="popover-link" onClick={()=>{setNotify(false);go('/alerts')}}>Open alert center <ArrowRight size={13}/></button></div>}</div>
        <div className="pop-anchor"><button className="profile-button" onClick={()=>{setProfile(!profile);setNotify(false)}}><span className="avatar">MP</span><span className="profile-name">Maya Patel</span><ChevronDown size={13}/></button>{profile&&<div className="popover-card profile-pop"><div className="profile-pop-name">Maya Patel<small>Platform engineer</small></div><button onClick={()=>showToast('Profile settings are local-demo only')}>Account preferences</button><button onClick={()=>showToast('Signed in to local demo workspace')}>Workspace access</button></div>}</div>
      </div></header>
      <div className="content-area">
        {loading?<div className="loading-area"><div className="skeleton title-skeleton"/><div className="skeleton row-skeleton"/><div className="skeleton chart-skeleton"/><span>Loading demo workspace…</span></div>:loadError?<div className="error-panel"><AlertTriangle/><h2>Workspace data unavailable</h2><p>The local demo provider could not load its sample records.</p><button className="button primary" onClick={()=>window.location.reload()}><RefreshCw size={14}/> Retry</button></div>:<><div className="page-heading"><div><div className="eyebrow">{meta.eyebrow}<span className="data-label">LOCAL DEMO DATA</span></div><h1 className="display">{meta.title}</h1><p>{meta.description}</p></div><div className="heading-actions">{['/','/deployments','/incidents','/changes','/services'].includes(pathname)&&<button className="button primary" onClick={()=>pathname==='/deployments'?simulateDeploy():setCreateOpen(true)}><Plus size={15}/>{pathname==='/deployments'?'Simulate deployment':pathname==='/incidents'?'New incident':pathname==='/changes'?'Request change':pathname==='/services'?'Add service':'Create action'}</button>}</div></div>
        {pathname==='/'&&current&&<Dashboard data={{...current,services:visibleServices,deployments:filteredDeployments,incidents:filteredIncidents,alerts:filteredAlerts}} env={env} go={go} open={setDrawer}/>}
        {pathname==='/deployments'&&current&&<Deployments rows={filteredDeployments} env={env} search={search} setSearch={setSearch} onSimulate={simulateDeploy} open={setDrawer}/>}
        {pathname==='/release-history'&&current&&<ReleaseHistory rows={filteredDeployments} open={setDrawer}/>}
        {pathname==='/pipelines'&&current&&<Pipelines rows={filteredDeployments} open={setDrawer}/>}
        {pathname==='/services'&&current&&<ServicesPage rows={visibleServices} search={search} setSearch={setSearch} open={s=>{setDrawer(s);}} go={go}/>}
        {pathname==='/service-catalog'&&current&&<ServicesPage rows={visibleServices} search={search} setSearch={setSearch} open={setDrawer} go={go} catalog/>}
        {pathname==='/dependencies'&&current&&<Dependencies services={visibleServices} open={setDrawer}/>}
        {pathname==='/incidents'&&<Incidents rows={filteredIncidents} filter={filter} setFilter={setFilter} search={search} setSearch={setSearch} ack={acknowledge} open={setDrawer}/>}
        {pathname==='/alerts'&&<Alerts rows={filteredAlerts} filter={filter} setFilter={setFilter} search={search} setSearch={setSearch} act={actAlert} open={setDrawer}/>}
        {pathname==='/runbooks'&&current&&<Runbooks rows={current.runbooks} search={search} setSearch={setSearch} open={setDrawer}/>}
        {pathname==='/changes'&&<Changes rows={changeState} env={env} open={setDrawer} approve={approve}/>}
        {pathname==='/environments'&&current&&<Environments rows={current.environments} services={visibleServices} deployments={filteredDeployments} setEnv={setEnv}/>}
        {pathname==='/servers'&&current&&<Inventory rows={current.servers.filter(x=>(env==='ALL'||x.environment===env)&&(serviceFilter==='ALL SERVICES'||x.service===serviceFilter))} search={search} setSearch={setSearch} open={setDrawer}/>}
        {pathname==='/containers'&&current&&<Containers services={visibleServices} open={setDrawer}/>}
        {pathname==='/infrastructure'&&current&&<Infrastructure services={visibleServices}/>}
        {pathname==='/metrics'&&current&&<MetricsPanel data={current.metrics} services={current.services} period={period}/>}
        {pathname==='/logs'&&current&&<LogsPanel rows={current.logs.filter(x=>(env==='ALL'||x.environment===env)&&(serviceFilter==='ALL SERVICES'||x.service===serviceFilter))} search={search} setSearch={setSearch}/>}
        {pathname==='/traces'&&current&&<TracesPanel rows={current.traces.filter(x=>serviceFilter==='ALL SERVICES'||x.service===serviceFilter)} open={setDrawer}/>}
        {pathname==='/cost'&&current&&<CostPanel rows={current.costs.filter(x=>(env==='ALL'||x.environment===env)&&(serviceFilter==='ALL SERVICES'||x.service===serviceFilter))}/>}
        {pathname==='/optimization'&&current&&<Optimization rows={current.costs}/>}
        {pathname==='/security'&&<SecurityPanel/>}
        {pathname==='/audit'&&current&&<AuditPanel rows={current.auditEvents} search={search} setSearch={setSearch}/>}
        {pathname==='/engineering'&&current&&<Engineering data={current.metrics} deployments={filteredDeployments}/>}
        {pathname==='/reliability'&&current&&<Reliability services={current.services} metrics={current.metrics}/>}
        {pathname==='/reports'&&current&&<Reports go={go} showToast={showToast}/>}
        {!pageMeta[pathname]&&current&&<ServiceDetail name={decodeURIComponent(pathname.split('/').pop()||'')} services={current.services} open={setDrawer} go={go}/>}
        </>}
        <footer className="footer-note"><span><span className="pulse-dot"/> Demo workspace · No infrastructure connections</span><span>Updated moments ago <span className="footer-divider">·</span> Documentation <CircleHelp size={12}/></span></footer>
      </div>
    </main>
        {palette&&<CommandPalette close={()=>setPalette(false)} go={go} data={current} openRecord={setDrawer} setEnvironment={setEnv} createIncident={()=>{setLocation('/incidents');setCreateOpen(true)}}/>}
    {drawer!==null&&<DetailDrawer item={drawer} close={()=>setDrawer(null)} go={go} toast={showToast}/>}
    {createOpen&&<CreateDialog path={pathname} close={()=>setCreateOpen(false)} create={createRecord}/>}
    {toast&&<div className={`toast-message ${toast.kind==='warning'?'toast-warning':''}`}><CheckCircle2 size={16}/>{toast.message}<button aria-label="Dismiss notification" onClick={()=>setToast(null)}><X size={14}/></button></div>}
  </div>;
}

function Panel({title,detail,action,children,className=''}:{title:string;detail?:string;action?:ReactNode;children:ReactNode;className?:string}){return <section className={`panel section-panel ${className}`}><div className="panel-head"><div><h2>{title}</h2>{detail&&<p>{detail}</p>}</div>{action}</div>{children}</section>}
function Stat({label,value,delta,icon:Icon,tone='good'}:{label:string;value:string;delta:string;icon:ElementType;tone?:string}){return <div className="panel stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon ${tone}`}><Icon size={15}/></span></div><div className="stat-value display">{value}</div><div className={`stat-delta ${tone}`}><ArrowUpRight size={13}/>{delta}</div></div>}
function Status({value}:{value:string}){const type=value.toLowerCase().includes('critical')||value.includes('SEV-1')||value==='Failed'||value==='Error'||value==='Denied'?'red':value.toLowerCase().includes('degrad')||value.includes('SEV-2')||value==='Warning'||value==='Pending'||value==='Firing'||value==='High'||value==='Medium'||value==='At risk'?'amber':value==='Suppressed'?'muted':'green';return <span className={`status-pill ${type}`}><i/>{value}</span>}
function SearchBox({value,onChange,placeholder='Search records…'}:{value:string;onChange:(s:string)=>void;placeholder?:string}){return <label className="inline-search"><Search size={14}/><input aria-label={placeholder} data-testid="input-global-search" placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/>{value&&<button onClick={()=>onChange('')} aria-label="Clear search"><X size={13}/></button>}</label>}
function SortControl({value,onChange,options}:{value:string;onChange:(value:string)=>void;options:string[]}){return <label className="filter-select sort-select"><SlidersHorizontal size={13}/><select aria-label="Sort records" value={value} onChange={e=>onChange(e.target.value)}>{options.map(option=><option key={option}>{option}</option>)}</select><ChevronDown size={12}/></label>}
function Toolbar({search,setSearch,filter,setFilter,filters=['All','Critical','Warning','Info']}:{search:string;setSearch:(s:string)=>void;filter?:string;setFilter?:(s:string)=>void;filters?:string[]}){return <div className="table-toolbar"><SearchBox value={search} onChange={setSearch}/>{filter&&setFilter&&<label className="filter-select"><Filter size={13}/><select value={filter} onChange={e=>setFilter(e.target.value)}>{filters.map(f=><option key={f}>{f}</option>)}</select><ChevronDown size={12}/></label>}<button className="button subtle" onClick={()=>setSearch('')}><SlidersHorizontal size={14}/>Filters</button></div>}
function DataTable({headers,children}:{headers:string[];children:ReactNode}){return <div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}

function Dashboard({data,env,go,open}:{data:Data;env:string;go:(p:string)=>void;open:(x:unknown)=>void}) {
 const services=data.services.filter(s=>env==='ALL'||s.environment===env); const active=data.incidents.filter(x=>x.status!=='Resolved').length; const firing=data.alerts.filter(x=>x.status==='Firing').length;
 return <><div className="stat-grid"><Stat label="Services healthy" value={`${services.filter(s=>s.health==='Healthy').length} / ${services.length}`} delta="2 services need attention" icon={Activity}/><Stat label="Active incidents" value={String(active).padStart(2,'0')} delta="1 high-severity response" icon={AlertOctagon} tone="amber"/><Stat label="Deployments · 24h" value="18" delta="94.4% successful" icon={Package}/><Stat label="Firing alerts" value={String(firing).padStart(2,'0')} delta="Across 3 service groups" icon={Bell} tone="red"/></div>
 <div className="dashboard-main-grid"><Panel title="Service health" detail="Production fleet · current state" action={<button className="link-button" onClick={()=>go('/services')}>View catalog <ArrowRight size={13}/></button>}><div className="health-list">{services.slice(0,6).map(s=><button key={s.id} className="health-row" onClick={()=>open(s)}><span className={`health-mark ${s.health.toLowerCase()}`}><Activity size={14}/></span><span className="health-main"><b>{s.name}</b><small>{s.team} · {s.tier}</small></span><span className="health-slo"><small>SLO</small><b>{s.slo}%</b></span><Status value={s.health}/><ChevronRight size={14} className="row-chevron"/></button>)}</div></Panel>
 <Panel title="Release risk" detail="Signals that may affect the next promotion" action={<span className="tiny-tag">UPDATED 2M AGO</span>}><div className="risk-list"><button className="risk-row" onClick={()=>go('/incidents')}><span className="risk-index red">01</span><span><b>Checkout latency elevated</b><small>checkout-api · p95 +38% after REL-1048</small></span><Status value="High"/></button><button className="risk-row" onClick={()=>go('/changes')}><span className="risk-index amber">02</span><span><b>Production change awaiting review</b><small>CHG-396 · connection pool tuning</small></span><Status value="Pending"/></button><button className="risk-row" onClick={()=>go('/reliability')}><span className="risk-index amber">03</span><span><b>Search error budget at 71%</b><small>search-index · burn rate 2.1×</small></span><Status value="Warning"/></button></div></Panel></div>
 <div className="dashboard-lower-grid"><Panel title="Request health" detail="Latency and throughput · last 24 hours" action={<button className="icon-button small" onClick={()=>go('/metrics')} aria-label="Open metrics"><ExternalLink size={14}/></button>}><div className="chart-key"><span><i className="key-line teal"/>p95 latency</span><span><i className="key-line blue"/>throughput</span><b>318<span> ms</span><small>p95 now</small></b></div><div className="chart-box"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.metrics}><defs><linearGradient id="areaTeal" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#45b69d" stopOpacity={.23}/><stop offset="100%" stopColor="#45b69d" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="time" tick={{fontSize:10,fill:'var(--chart-label)'}} axisLine={false} tickLine={false} interval={5}/><YAxis hide/><Tooltip contentStyle={{background:'var(--tooltip-bg)',border:'1px solid var(--tooltip-border)',borderRadius:8,color:'var(--tooltip-text)'}}/><Area type="monotone" dataKey="latency" stroke="#49b99f" fill="url(#areaTeal)" strokeWidth={2} name="p95 latency"/></AreaChart></ResponsiveContainer></div></Panel>
 <Panel title="Recent activity" detail="Latest changes across your workspace" action={<button className="link-button" onClick={()=>go('/audit')}>Audit trail <ArrowRight size={13}/></button>}><div className="activity-list">{data.auditEvents.slice(0,5).map((e,i)=><button className="activity-row" key={e.id} onClick={()=>open(e)}><span className={`activity-icon a${i%3}`}>{i===0?<Package size={14}/>:i===1?<ShieldCheck size={14}/>:<GitBranch size={14}/>}</span><span><b>{e.actor}</b> {e.action}<small>{e.resource} <span>·</span> {e.time.slice(11,16)} UTC</small></span><Status value={e.outcome}/></button>)}</div></Panel></div>
 <div className="section-caption"><span>ENVIRONMENT POSTURE</span><button className="link-button" onClick={()=>go('/environments')}>All environments <ArrowRight size={13}/></button></div><div className="env-card-grid">{data.environments.map(e=><button className="panel env-card" key={e.id} onClick={()=>go('/environments')}><div className="env-card-top"><span className="env-symbol"><Globe2 size={15}/></span><Status value={e.status}/></div><b>{e.name}</b><small>{e.region} <span>·</span> {e.services} services</small><div className="env-version mono">{e.version}<ArrowRight size={13}/></div></button>)}</div>
 </>;
}

function Deployments({rows,env,search,setSearch,onSimulate,open}:{rows:Deployment[];env:string;search:string;setSearch:(s:string)=>void;onSimulate:()=>void;open:(x:unknown)=>void}){const [sort,setSort]=useState('Newest first');const list=rows.filter(r=>(env==='ALL'||r.environment===env)&&(r.service+r.id+r.author).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='Service A–Z'?a.service.localeCompare(b.service):sort==='Status'?a.status.localeCompare(b.status):rows.indexOf(a)-rows.indexOf(b));return <><div className="stat-grid compact"><Stat label="Deployments today" value="18" delta="↑ 3 from yesterday" icon={Package}/><Stat label="Success rate" value="94.4%" delta="17 succeeded · 1 failed" icon={CheckCircle2}/><Stat label="Awaiting approval" value="02" delta="Production gated" icon={LockKeyhole} tone="amber"/><Stat label="Median duration" value="6m 42s" delta="Down 18 seconds" icon={Timer}/></div><Panel title="Recent deployments" detail="All release events are simulated demo records" action={<button className="button primary" onClick={onSimulate}><Plus size={14}/>Simulate deployment</button>}><div className="table-toolbar"><SearchBox value={search} onChange={setSearch}/><SortControl value={sort} onChange={setSort} options={['Newest first','Service A–Z','Status']}/><span className="result-count">{list.length} deployments</span></div><DataTable headers={['RELEASE','SERVICE','ENVIRONMENT','VERSION','STATUS','TRIGGERED BY','DURATION','']}><>{list.slice(0,12).map(d=><tr key={d.id} onClick={()=>open(d)} className="click-row"><td className="mono accent-text">{d.id}</td><td><b>{d.service}</b><small className="cell-sub mono">{d.commit}</small></td><td><span className="env-chip">{d.environment}</span></td><td className="mono">{d.version}</td><td><Status value={d.status}/></td><td>{d.author}</td><td className="mono">{d.duration}</td><td><button className="icon-button small" aria-label={`Details for ${d.id}`} onClick={e=>{e.stopPropagation();open(d)}}><MoreHorizontal size={15}/></button></td></tr>)}</></DataTable></Panel></>}
function ReleaseHistory({rows,open}:{rows:Deployment[];open:(x:unknown)=>void}){return <div className="two-column"><Panel title="Release timeline" detail="Deployment history across all environments"><div className="timeline">{rows.slice(0,12).map(d=><button className="timeline-item" key={d.id} onClick={()=>open(d)}><span className={`timeline-dot ${d.status==='Failed'?'red':d.status==='Running'?'amber':''}`}/><span className="timeline-date mono">{d.time}</span><span className="timeline-body"><b>{d.service} <span>{d.version}</span></b><small>{d.author} · {d.environment} · {d.id}</small></span><Status value={d.status}/></button>)}</div></Panel><div><div className="stat-grid vertical-stats"><Stat label="Release frequency" value="3.8 / day" delta="↑ 12% this week" icon={GitBranch}/><Stat label="Change failure rate" value="5.6%" delta="Within target · < 8%" icon={AlertTriangle}/><Stat label="Mean time to restore" value="24m" delta="↓ 6m this month" icon={RefreshCw}/></div><Panel title="Deployment outcomes" detail="Last 30 days"><div className="outcome-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{name:'W1',pass:32,fail:2},{name:'W2',pass:38,fail:1},{name:'W3',pass:29,fail:3},{name:'W4',pass:42,fail:2}]}><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="name" tick={{fontSize:10,fill:'var(--chart-label)'}} axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="pass" stackId="a" fill="#48b49a" radius={[3,3,0,0]}/><Bar dataKey="fail" stackId="a" fill="#df7772" radius={[3,3,0,0]}/></BarChart></ResponsiveContainer></div></Panel></div></div>}
function Pipelines({rows,open}:{rows:Deployment[];open:(x:unknown)=>void}){return <><div className="stat-grid compact"><Stat label="Pipeline runs" value="42" delta="Across 9 services" icon={Workflow}/><Stat label="Passing" value="39" delta="92.8% pass rate" icon={CheckCircle2}/><Stat label="In progress" value="02" delta="Longest run 8m 12s" icon={LoaderCircle} tone="amber"/><Stat label="Queued" value="01" delta="Runner pool healthy" icon={Clock3}/></div><Panel title="Latest pipeline runs" detail="Select a run to inspect stage details"><DataTable headers={['RUN','SERVICE','BRANCH','STAGES','RESULT','DURATION','STARTED']}><>{rows.slice(0,10).map((d,i)=><tr className="click-row" key={d.id} onClick={()=>open(d)}><td className="mono accent-text">#{218-i}</td><td><b>{d.service}</b></td><td className="mono">main</td><td><div className="stage-strip">{[0,1,2,3].map(n=><i key={n} className={n===3&&d.status==='Failed'?'stage-fail':n===3&&d.status==='Running'?'stage-active':'stage-pass'}/>)}</div><small className="cell-sub">Build · Unit · Integration · Deploy</small></td><td><Status value={d.status}/></td><td className="mono">{d.duration}</td><td>{d.time}</td></tr>)}</></DataTable></Panel></>}

function ServicesPage({rows,search,setSearch,open,go,catalog=false}:{rows:Service[];search:string;setSearch:(s:string)=>void;open:(x:unknown)=>void;go:(p:string)=>void;catalog?:boolean}){const [sort,setSort]=useState('Name A–Z');const list=rows.filter(s=>(s.name+s.team+s.owner+s.tier).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='Health risk'?b.health.localeCompare(a.health):sort==='Owner'?a.owner.localeCompare(b.owner):a.name.localeCompare(b.name));return <><div className="stat-grid compact"><Stat label="Registered services" value={String(rows.length).padStart(2,'0')} delta="Across 7 owning teams" icon={Boxes}/><Stat label="Tier 0 / 1" value="06" delta="Customer critical" icon={ShieldCheck}/><Stat label="Ownership coverage" value="100%" delta="All records have an owner" icon={CheckCircle2}/><Stat label="Dependencies" value="24" delta="Mapped relationships" icon={Network}/></div><Panel title={catalog?'Ownership & metadata':'Service ownership'} detail="Service data is local demo content. Select a row for the service profile."><div className="table-toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Search service, team, owner…"/><SortControl value={sort} onChange={setSort} options={['Name A–Z','Owner','Health risk']}/><button className="button subtle" onClick={()=>go('/dependencies')}><Network size={14}/>Dependency map</button></div><DataTable headers={['SERVICE','OWNER / TEAM','TIER','HEALTH','SLO TARGET','DEPENDENCIES','VERSION']}><>{list.map(s=><tr key={s.id} className="click-row" onClick={()=>open(s)}><td><span className="service-glyph"><Boxes size={15}/></span><span className="service-cell"><b>{s.name}</b><small>{catalog?s.description:s.region}</small></span></td><td>{s.owner}<small className="cell-sub">{s.team}</small></td><td><span className={`tier-chip ${s.tier==='Tier 0'?'tier-zero':''}`}>{s.tier}</span></td><td><Status value={s.health}/></td><td className="mono">{s.slo}%</td><td><div className="dependency-chips">{s.dependencies.map(dep=><span key={dep}>{dep}</span>)}</div></td><td className="mono">{s.version}</td></tr>)}</></DataTable><Pagination count={list.length}/></Panel></>}

function Dependencies({services,open}:{services:Service[];open:(x:unknown)=>void}){return <><div className="dependency-toolbar"><span><span className="legend-dot healthy"/> Healthy <span className="legend-dot warning"/> Degraded</span><span className="mono">PRODUCTION · 10 NODES · 14 EDGES</span><button className="button subtle" onClick={()=>open(services[0])}><Network size={14}/>Impact analysis</button></div><Panel title="Service dependency topology" detail="Select a service node to inspect ownership and impact paths." className="graph-panel"><div className="dependency-canvas soft-grid"><svg className="graph-lines" viewBox="0 0 900 430" preserveAspectRatio="none"><path d="M165 215 C260 215 285 105 380 105 M165 215 C265 215 275 215 380 215 M165 215 C260 215 290 325 380 325 M475 105 C555 105 560 180 640 180 M475 215 C555 215 565 180 640 180 M475 325 C560 325 565 180 640 180 M715 180 C780 180 785 180 835 180" /><path className="risk-path" d="M165 215 C260 215 285 105 380 105 M475 105 C555 105 560 180 640 180"/></svg>{[['checkout-api','Commerce · Tier 1','critical',5,40],['payments-ledger','Payments · Tier 0','good',29,16],['inventory-core','Commerce · Tier 1','good',29,43],['search-index','Discovery · Tier 2','warning',29,70],['fraud-engine','Risk · Tier 1','good',59,34],['catalog-api','Commerce · Tier 2','good',59,62],['identity-gateway','Platform · Tier 0','good',76,34],['session-store','Platform · Tier 1','good',76,62],['event-stream','Platform · Tier 1','good',88,47],['billing-worker','Finance · Tier 1','critical',59,86]].map(([name,sub,tone,x,y])=>{const s=services.find(z=>z.name===name);return <button key={name} className={`graph-node ${tone}`} style={{left:`${x}%`,top:`${y}%`}} onClick={()=>s&&open(s)}><span className="node-led"/><b>{name}</b><small>{sub}</small></button>})}</div><div className="graph-caption"><span><span className="caption-line"/> Request dependency <span className="caption-line risk"/> Elevated risk path</span><span>Customer impact propagates upstream → downstream</span></div></Panel><div className="impact-callout"><div className="impact-icon"><AlertTriangle size={17}/></div><div><b>Potential customer impact detected</b><p>checkout-api degradation may affect <strong>3 downstream paths</strong>, including payment authorization and inventory reservation.</p></div><button className="link-button" onClick={()=>open(services[0])}>Inspect impact <ArrowRight size={13}/></button></div></>}

function Incidents({rows,filter,setFilter,search,setSearch,ack,open}:{rows:Incident[];filter:string;setFilter:(s:string)=>void;search:string;setSearch:(s:string)=>void;ack:(id:string)=>void;open:(x:unknown)=>void}){return <><div className="stat-grid compact"><Stat label="Open incidents" value="03" delta="1 requires immediate response" icon={AlertOctagon} tone="red"/><Stat label="SEV-1 / SEV-2" value="02" delta="1 unacknowledged" icon={ShieldAlert} tone="amber"/><Stat label="MTTA · 30d" value="4m 18s" delta="↓ 21% from last month" icon={Timer}/><Stat label="Resolved today" value="07" delta="Median 18 minutes" icon={CheckCircle2}/></div><Panel title="Incident queue" detail="Local acknowledgement updates this demo view."><Toolbar search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} filters={['All','SEV-1','SEV-2','SEV-3','Investigating','Mitigating','Resolved']}/><div className="incident-list">{rows.map(i=><div className="incident-card" key={i.id}><button className="incident-main" onClick={()=>open(i)}><span className={`incident-severity ${i.severity==='SEV-1'?'sev1':i.severity==='SEV-2'?'sev2':'sev3'}`}>{i.severity}</span><span><b>{i.title}</b><small>{i.id} <span>·</span> {i.service} <span>·</span> {i.started}</small></span></button><div className="incident-impact"><span>{i.impact}</span><small>Commander: {i.owner}</small></div><Status value={i.status}/>{!i.acknowledged?<button className="button subtle" onClick={()=>ack(i.id)}><Check size={14}/>Acknowledge</button>:<span className="ack-label"><Check size={13}/>Acknowledged</span>}</div>)}</div>{rows.length===0&&<EmptyState title="No incidents found" detail="Try another filter or search term."/>}</Panel><Panel title="Response timeline" detail="Latest incident event stream"><div className="mini-events"><span className="event-line"/>{[['14:36:11','INC-8421 · detected','p95 latency burn threshold crossed','red'],['14:38:02','INC-8421 · assigned','Maya Patel joined response','amber'],['14:41:28','INC-8420 · mitigated','Queue consumers scaled to 8','green']].map(e=><div className="mini-event" key={e[0]}><span className={`mini-dot ${e[3]}`}/><span className="mono">{e[0]}</span><b>{e[1]}</b><small>{e[2]}</small></div>)}</div></Panel></>}

function Alerts({rows,filter,setFilter,search,setSearch,act,open}:{rows:Alert[];filter:string;setFilter:(s:string)=>void;search:string;setSearch:(s:string)=>void;act:(id:string,a:'Acknowledged'|'Resolved'|'Suppressed')=>void;open:(x:unknown)=>void}){return <><div className="stat-grid compact"><Stat label="Firing now" value={String(rows.filter(a=>a.status==='Firing').length).padStart(2,'0')} delta="Signals needing triage" icon={Bell} tone="red"/><Stat label="Critical" value={String(rows.filter(a=>a.severity==='Critical').length).padStart(2,'0')} delta="Across 2 services" icon={AlertOctagon} tone="amber"/><Stat label="Resolved · 24h" value="17" delta="Median resolution 9m" icon={CheckCircle2}/><Stat label="Suppressed" value={String(rows.filter(a=>a.status==='Suppressed').length).padStart(2,'0')} delta="Policy-controlled windows" icon={Radio}/></div><Panel title="Alert stream" detail="Acknowledge, resolve, or suppress actions update local demo state only."><Toolbar search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} filters={['All','Critical','Warning','Info','Firing','Acknowledged','Resolved','Suppressed']}/><DataTable headers={['SEVERITY','ALERT','SERVICE','ENVIRONMENT','SOURCE','FIRST SEEN','STATE','ACTIONS']}><>{rows.slice(0,16).map(a=><tr key={a.id}><td><Status value={a.severity}/></td><td className="clickable-text" onClick={()=>open(a)}><b>{a.title}</b><small className="cell-sub mono">{a.id}</small></td><td>{a.service}</td><td><span className="env-chip">{a.environment}</span></td><td className="mono">{a.source}</td><td>{a.time}</td><td><Status value={a.status}/></td><td><div className="row-actions">{a.status==='Firing'?<><button className="text-action" onClick={()=>act(a.id,'Acknowledged')}>Acknowledge</button><button className="text-action" onClick={()=>act(a.id,'Resolved')}>Resolve</button><button className="text-action muted-action" onClick={()=>act(a.id,'Suppressed')}>Suppress</button></>:<button className="icon-button small" onClick={()=>open(a)} aria-label={`Inspect alert ${a.id}`}><ExternalLink size={13}/></button>}</div></td></tr>)}</></DataTable>{rows.length===0&&<EmptyState title="Nothing in this view" detail="No alerts match your current filters."/>}<Pagination count={rows.length}/></Panel></>}

function Runbooks({rows,search,setSearch,open}:{rows:Runbook[];search:string;setSearch:(s:string)=>void;open:(x:unknown)=>void}){const list=rows.filter(x=>(x.title+x.category+x.owner+x.description).toLowerCase().includes(search.toLowerCase()));return <><div className="runbook-hero"><div className="book-icon"><FileText size={22}/></div><div><span className="eyebrow">ON-CALL FIELD GUIDE</span><h2>Good response starts with context.</h2><p>Search maintained playbooks. Each guide is a demo record; follow your team's verified procedure in production.</p></div><SearchBox value={search} onChange={setSearch} placeholder="Search runbooks…"/></div><div className="runbook-grid">{list.map(r=><button className="panel runbook-card" key={r.id} onClick={()=>open(r)}><div className="runbook-card-top"><span className="runbook-cat">{r.category}</span><span className="mono">{r.id}</span></div><h3>{r.title}</h3><p>{r.description}</p><div className="runbook-footer"><span>{r.owner}</span><span>{r.updated}<ArrowRight size={13}/></span></div></button>)}</div>{list.length===0&&<EmptyState title="No runbooks found" detail="Try a shorter search."/>}</>}

function Changes({rows,env,open,approve}:{rows:Change[];env:string;open:(x:unknown)=>void;approve:(id:string)=>void}){const [search,setSearch]=useState('');const [risk,setRisk]=useState('All risk');const list=rows.filter(x=>(env==='ALL'||x.environment===env)&&(risk==='All risk'||x.risk===risk)&&(x.title+x.service+x.id+x.requester).toLowerCase().includes(search.toLowerCase()));return <><div className="approval-banner"><div className="approval-lock"><LockKeyhole size={17}/></div><div><b>Production changes require two-person approval</b><p>Approval controls are simulated. Production requests remain gated in this local demo.</p></div><span className="tiny-tag">POLICY ENFORCED</span></div><Panel title="Change requests" detail="Risk, rollout window, and approval state"><div className="table-toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Search change requests…"/><label className="filter-select"><Filter size={13}/><select value={risk} onChange={e=>setRisk(e.target.value)}><option>All risk</option><option>Low</option><option>Medium</option><option>High</option></select><ChevronDown size={12}/></label></div><DataTable headers={['CHANGE','SERVICE','TARGET','REQUESTER','RISK','WINDOW','STATUS','REVIEW']}><>{list.map(c=><tr key={c.id} className="click-row"><td onClick={()=>open(c)}><b>{c.title}</b><small className="cell-sub mono">{c.id}</small></td><td>{c.service}</td><td><span className="env-chip">{c.environment}</span></td><td>{c.requester}</td><td><Status value={c.risk}/></td><td className="mono">{c.window}</td><td><Status value={c.status}/></td><td>{c.status==='Pending'?<button className="button small-button" onClick={()=>approve(c.id)}>Review</button>:<button className="icon-button small" onClick={()=>open(c)} aria-label={`Details for ${c.id}`}><ExternalLink size={13}/></button>}</td></tr>)}</></DataTable>{list.length===0&&<EmptyState title="No change requests found" detail="Adjust the environment, risk, or search filters."/>}</Panel></>}

function Environments({rows,services,deployments,setEnv}:{rows:Environment[];services:Service[];deployments:Deployment[];setEnv:(s:string)=>void}){return <><div className="env-overview-grid">{rows.map(e=><div className="panel environment-large" key={e.id}><div className="environment-large-head"><div><span className="eyebrow">{e.region}</span><h2>{e.name}</h2></div><Status value={e.status}/></div><div className="env-big-metrics"><div><b>{services.filter(s=>s.health==='Healthy').length}</b><small>Healthy services</small></div><div><b>{e.services}</b><small>Registered services</small></div><div><b>{deployments.filter(d=>d.environment===e.name.toUpperCase()).length}</b><small>Recent releases</small></div></div><div className="env-release"><span>Current release channel</span><b className="mono">{e.version}</b></div><button className="button subtle full-width" onClick={()=>setEnv(e.name.toUpperCase())}>Set active environment <ArrowRight size={13}/></button></div>)}</div><Panel title="Environment health checks" detail="Latest synthetic and runtime checks"><DataTable headers={['ENVIRONMENT','ENDPOINT PROBES','DATABASE','QUEUE LAG','DEPLOYMENT GATE','LAST CHECK']}><>{rows.map((e,i)=><tr key={e.id}><td><b>{e.name}</b></td><td><Status value="Healthy"/></td><td><Status value="Healthy"/></td><td><Status value={i===1?'Warning':'Healthy'}/></td><td><Status value="Enabled"/></td><td className="mono">14:{String(38-i*3).padStart(2,'0')} UTC</td></tr>)}</></DataTable></Panel></>}

function Inventory({rows,search,setSearch,open}:{rows:ServerRecord[];search:string;setSearch:(s:string)=>void;open:(x:unknown)=>void}){const list=rows.filter(x=>(x.name+x.service+x.region+x.environment).toLowerCase().includes(search.toLowerCase()));return <><div className="stat-grid compact"><Stat label="Compute instances" value={String(rows.length).padStart(2,'0')} delta="Across 3 environments" icon={Server}/><Stat label="Average CPU" value="48.2%" delta="Fleet-wide · healthy" icon={Activity}/><Stat label="Memory pressure" value="02" delta="Nodes above 80%" icon={Database} tone="amber"/><Stat label="Regions" value="02" delta="us-east-1 · us-west-2" icon={Globe2}/></div><Panel title="Server inventory" detail="Sample infrastructure inventory · no cloud connection"><div className="table-toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Search host, service, region…"/><button className="button subtle" onClick={()=>{navigator.clipboard?.writeText(['instance,service,environment,region,cpu,memory',...list.map(s=>`${s.name},${s.service},${s.environment},${s.region},${s.cpu},${s.memory}`)].join('\\n'))}}><Download size={14}/>Export</button></div><DataTable headers={['INSTANCE','SERVICE','ENVIRONMENT','REGION','TYPE','CPU','MEMORY','STATE']}><>{list.map(s=><tr key={s.id} className="click-row" onClick={()=>open(s)}><td className="mono accent-text">{s.name}</td><td>{s.service}</td><td><span className="env-chip">{s.environment}</span></td><td className="mono">{s.region}</td><td className="mono">{s.type}</td><td><UsageBar value={s.cpu}/></td><td><UsageBar value={s.memory}/></td><td><Status value={s.status}/></td></tr>)}</></DataTable><Pagination count={list.length}/></Panel></>}
function UsageBar({value}:{value:number}){return <div className="usage"><span className="usage-track"><i className={value>80?'usage-high':''} style={{width:`${value}%`}}/></span><span className="mono">{value}%</span></div>}
function Containers({services,open}:{services:Service[];open:(x:unknown)=>void}){return <><div className="stat-grid compact"><Stat label="Running pods" value="146" delta="Across 3 namespaces" icon={Box}/><Stat label="Ready" value="142 / 146" delta="97.3% availability" icon={CheckCircle2}/><Stat label="Restarting" value="03" delta="2 workloads impacted" icon={RefreshCw} tone="amber"/><Stat label="Deployments" value="38" delta="Kubernetes workloads" icon={Boxes}/></div><Panel title="Workload inventory" detail="Namespace: platform · commerce · observability"><DataTable headers={['WORKLOAD','NAMESPACE','READY','RESTARTS','CPU','MEMORY','IMAGE','HEALTH']}><>{services.map((s,i)=><tr key={s.id} className="click-row" onClick={()=>open(s)}><td><b>{s.name}</b></td><td>{i%2?'platform':'commerce'}</td><td className="mono">{i===0?'4/5':'3/3'}</td><td className="mono">{i===0?'7':i%5}</td><td><UsageBar value={25+i*4%65}/></td><td><UsageBar value={39+i*3%51}/></td><td className="mono">{s.name}:{s.version}</td><td><Status value={s.health==='Critical'?'Degraded':s.health}/></td></tr>)}</></DataTable></Panel></>}
function Infrastructure({services}:{services:Service[]}){return <><div className="infra-summary"><div><span className="eyebrow">RELATIONSHIPS</span><h2>Runtime, data, and network</h2><p>Connected model of the platform. Edges describe illustrative dependencies only.</p></div><span className="tiny-tag">DEMO TOPOLOGY</span></div><div className="infra-grid">{[{title:'Compute clusters',icon:Server,items:['prod-core-az1 · 18 nodes','prod-core-az2 · 16 nodes','uat-shared · 8 nodes'],status:'Healthy'},{title:'Data services',icon:Database,items:['ledger-postgres · multi-AZ','session-redis · 3 shards','search-opensearch · 6 nodes'],status:'Healthy'},{title:'Event fabric',icon:Radio,items:['kafka-prod · 12 brokers','event-stream · 24 partitions','consumer groups · 38'],status:'Degraded'},{title:'Network edge',icon:Globe2,items:['edge-gateway · 3 regions','private endpoints · 42','egress policies · 14'],status:'Healthy'}].map((g,i)=><section className="panel infra-card" key={g.title}><div className="infra-card-head"><span className="infra-icon"><g.icon size={17}/></span><Status value={g.status}/></div><h3>{g.title}</h3><div className="infra-items">{g.items.map(x=><div key={x}><span className="infra-bullet"/>{x}</div>)}</div><div className="infra-foot">Connected services <b>{[6,4,3,10][i]}</b><ArrowRight size={13}/></div></section>)}</div><Panel title="Service-to-infrastructure mapping" detail="Owners and runtime substrate"><div className="mapping-list">{services.slice(0,7).map((s,i)=><div className="mapping-row" key={s.id}><b>{s.name}</b><span className="mapping-connector"/><span className="infra-chip">{['prod-core-az1','ledger-postgres','kafka-prod','session-redis'][i%4]}</span><span className="mono">{s.region}</span><Status value={s.health}/></div>)}</div></Panel></>}

function MetricsPanel({data,services,period}:{data:Metric[];services:Service[];period:string}){const [service,setService]=useState('All services');const [dimensions,setDimensions]=useState<string[]>(['service']);return <><div className="selector-row"><label>Service<select value={service} onChange={e=>setService(e.target.value)}><option>All services</option>{services.map(s=><option key={s.id}>{s.name}</option>)}</select><ChevronDown size={12}/></label><span className="data-label">{service.toUpperCase()} · WINDOW · {period.toUpperCase()}</span></div><div className="metric-grid">{[{name:'Request latency · p95',key:'latency',value:'318 ms',delta:'↑ 12.4%',color:'#4bb79f',unit:'ms'},{name:'Error rate',key:'errorRate',value:'0.42%',delta:'↑ 0.08 pp',color:'#d77b70',unit:'%'},{name:'Request throughput',key:'throughput',value:'812 rpm',delta:'↓ 4.2%',color:'#69a9c7',unit:'rpm'},{name:'Compute utilization',key:'cpu',value:'48.2%',delta:'Stable',color:'#c9a45d',unit:'%'}].map((m,i)=><MetricChart key={m.key} config={m} data={data} index={i}/>)}</div><Panel title="Metric dimensions" detail="Toggle dimensions represented in the active query"><div className="dimension-chips">{['service','environment','region','status_code','availability_zone','deployment_version'].map(x=><button key={x} className={dimensions.includes(x)?'dimension-selected':''} aria-pressed={dimensions.includes(x)} onClick={()=>setDimensions(prev=>prev.includes(x)?prev.filter(d=>d!==x):[...prev,x])}>{x}<Plus size={12}/></button>)}</div></Panel></>}
function MetricChart({config,data,index}:{config:{name:string;key:string;value:string;delta:string;color:string;unit:string};data:Metric[];index:number}){return <Panel title={config.name} detail={`${config.delta} vs previous period`}><div className="metric-value">{config.value}<span className={index===1?'negative':''}>{config.delta}</span></div><div className="metric-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id={`metric-${index}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={config.color} stopOpacity={.23}/><stop offset="100%" stopColor={config.color} stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="time" hide/><YAxis hide/><Tooltip/><Area type="monotone" dataKey={config.key} stroke={config.color} strokeWidth={2} fill={`url(#metric-${index})`}/></AreaChart></ResponsiveContainer></div><div className="chart-foot"><span>00:00</span><span>12:00</span><span>NOW</span></div></Panel>}

function LogsPanel({rows,search,setSearch}:{rows:LogEntry[];search:string;setSearch:(s:string)=>void}){const [level,setLevel]=useState('All levels');const list=rows.filter(l=>(level==='All levels'||l.level===level)&&(l.message+l.service+l.traceId+l.level).toLowerCase().includes(search.toLowerCase()));return <><div className="log-controls"><SearchBox value={search} onChange={setSearch} placeholder="Search message, service, trace ID…"/><select value={level} onChange={e=>setLevel(e.target.value)}><option>All levels</option><option>INFO</option><option>WARN</option><option>ERROR</option></select><span className="env-chip">{envLabel(rows)}</span><button className="button subtle"><Download size={13}/>Export</button></div><Panel title="Log events" detail={`${list.length} matching structured records · local demo`}><div className="log-list">{list.slice(0,40).map(l=><button className="log-row" key={l.id} onClick={()=>navigator.clipboard?.writeText(l.traceId)}><span className="mono log-time">{l.time.slice(11,23)}</span><span className={`log-level ${l.level.toLowerCase()}`}>{l.level}</span><span className="log-service">{l.service}</span><span className="log-message">{l.message}</span><span className="mono log-trace">{l.traceId}</span><ExternalLink size={12}/></button>)}</div></Panel></>}
function envLabel(rows:LogEntry[]){return `${new Set(rows.map(x=>x.environment)).size} ENVIRONMENTS`}
function TracesPanel({rows,open}:{rows:Trace[];open:(x:unknown)=>void}){return <><div className="trace-summary"><div><b>1,284</b><span>traces / min</span></div><div><b>318 ms</b><span>p95 duration</span></div><div><b>0.42%</b><span>error rate</span></div><div className="trace-filter"><Search size={14}/><input placeholder="Filter traces"/></div></div><Panel title="Recent traces" detail="Representative request paths across service boundaries"><div className="trace-list">{rows.map(t=><button className="trace-row" key={t.id} onClick={()=>open(t)}><span className={`trace-status ${t.status==='Error'?'red':''}`}>{t.status==='Error'?<X size={13}/>:<Check size={13}/>}</span><span className="trace-route"><b>{t.route}</b><small>{t.service}</small></span><span className="trace-waterfall">{t.spans.map((s,i)=><i key={i} style={{width:`${Math.max(10,Math.min(40,s.duration/3))}%`,marginLeft:i===0?'0':`${s.duration%12}%`,background:i===1&&t.status==='Error'?'#d9736b':i===0?'#54b89f':'#6aa9c7'}} title={`${s.name}: ${s.duration}ms`}/>)}</span><span className="mono trace-time">{t.duration} ms</span><span className="mono trace-id">{t.id}</span></button>)}</div></Panel></>}

function CostPanel({rows}:{rows:CostRecord[]}){const total=rows.reduce((sum,x)=>sum+x.current,0);return <><div className="stat-grid compact"><Stat label="Month-to-date" value={money(total)} delta="↑ 6.8% vs prior month" icon={DollarSign} tone="amber"/><Stat label="Forecast" value={money(total*1.13)} delta="Within $42k budget" icon={Activity}/><Stat label="Budget utilization" value="72.4%" delta="28 days remaining" icon={SlidersHorizontal}/><Stat label="Unallocated spend" value={money(1830)} delta="3 cost groups" icon={AlertTriangle} tone="amber"/></div><div className="two-column"><Panel title="Daily spend trend" detail="Illustrative allocated cost · last 30 days"><div className="cost-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={Array.from({length:14},(_,i)=>({day:`Jun ${i+1}`,cost:8200+Math.sin(i*.58)*1300+i*90,budget:9800}))}><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="day" tick={{fontSize:10,fill:'var(--chart-label)'}} axisLine={false} tickLine={false}/><YAxis hide/><Tooltip/><Area type="monotone" dataKey="budget" stroke="#c7a55f" strokeDasharray="4 4" fill="none"/><Area type="monotone" dataKey="cost" stroke="#49b99f" fill="#49b99f" fillOpacity={.12}/></AreaChart></ResponsiveContainer></div></Panel><Panel title="Spend by category" detail="Month-to-date allocation"><div className="spend-breakdown">{[['Compute',42,'$18,420'],['Database',28,'$12,110'],['Network',18,'$7,684'],['Storage',12,'$5,260']].map(([x,p,v])=><div className="spend-row" key={x as string}><div><b>{x}</b><span>{v}</span></div><div className="spend-track"><i style={{width:`${p}%`}}/></div></div>)}</div></Panel></div><Panel title="Cost by service" detail="Daily cost allocation with month-over-month change"><DataTable headers={['SERVICE','CATEGORY','ENVIRONMENT','CURRENT MONTH','PRIOR MONTH','BUDGET','TREND']}><>{rows.slice(0,12).map(c=><tr key={c.id}><td><b>{c.service}</b></td><td>{c.category}</td><td><span className="env-chip">{c.environment}</span></td><td className="mono">{money(c.current)}</td><td className="mono">{money(c.previous)}</td><td className="mono">{money(c.budget)}</td><td className={c.current>c.previous?'negative':'positive'}>{c.current>c.previous?<ArrowUpRight size={13}/>:<ArrowDownRight size={13}/>} {((c.current/c.previous-1)*100).toFixed(1)}%</td></tr>)}</></DataTable></Panel></>}
function Optimization({rows}:{rows:CostRecord[]}){const opportunities=[{title:'Right-size checkout-api worker pool',service:'checkout-api',savings:1240,risk:'Low',detail:'Utilization p95 has stayed below 36% for 21 days.'},{title:'Review unattached storage volumes',service:'platform-storage',savings:860,risk:'Low',detail:'Four volumes have no active attachment or recent reads.'},{title:'Tune search-index reserved capacity',service:'search-index',savings:2180,risk:'Medium',detail:'Observed steady-state usage suggests a smaller commitment.'},{title:'Reduce cross-AZ transfer on event stream',service:'event-stream',savings:710,risk:'Medium',detail:'Consumer placement may reduce inter-zone traffic.'}];return <><div className="optimization-hero"><span className="optimization-mark"><ArrowDownRight size={22}/></span><div><span className="eyebrow">POTENTIAL MONTHLY SAVINGS</span><h2>$4,990 <small>across 4 opportunities</small></h2><p>Recommendations are illustrative. Validate workload constraints before applying changes.</p></div><button className="button subtle" onClick={()=>navigator.clipboard?.writeText('CloudOps local demo optimization estimate: $4,990/month')}>Copy summary</button></div><div className="opportunity-list">{opportunities.map((o,i)=><div className="panel opportunity" key={o.title}><div className="opp-number mono">0{i+1}</div><div className="opp-body"><h3>{o.title}</h3><p>{o.detail}</p><div><span className="env-chip">{o.service}</span><Status value={o.risk}/></div></div><div className="opp-savings"><b>{money(o.savings)}</b><small>potential / month</small></div><button className="button subtle" onClick={()=>{navigator.clipboard?.writeText(`${o.title}: ${money(o.savings)} monthly`);}}>Review</button></div>)}</div><p className="footnote">{rows.length} sample cost allocations considered · figures are demo estimates, not connected billing data.</p></>}

function SecurityPanel(){const findings=[['Public ingress rule permits broad CIDR','network-edge','Critical','Open'],['Container image has outdated base layer','checkout-api','High','In progress'],['TLS certificate rotation due in 19 days','identity-gateway','Medium','Open'],['S3 bucket logging configuration incomplete','billing-worker','Medium','Open'],['IAM role has unused permission scope','event-stream','Low','Accepted']];return <><div className="stat-grid compact"><Stat label="Posture score" value="87 / 100" delta="↑ 4 points this month" icon={ShieldCheck}/><Stat label="Critical findings" value="01" delta="Requires owner review" icon={ShieldAlert} tone="red"/><Stat label="Open findings" value="08" delta="Across 4 services" icon={LockKeyhole} tone="amber"/><Stat label="Policy checks" value="124 / 128" delta="96.9% compliant" icon={CheckCircle2}/></div><div className="security-callout"><ShieldAlert size={18}/><div><b>One critical network exposure needs review</b><p>Public ingress rule permits a broad CIDR range. Confirm intended access and remediation plan with the network owner.</p></div><button className="button subtle" onClick={()=>document.getElementById('finding-critical')?.scrollIntoView({behavior:'smooth'})}>Review finding</button></div><Panel title="Security findings" detail="Sample policy and vulnerability findings"><DataTable headers={['SEVERITY','FINDING','RESOURCE','OWNER','FIRST DETECTED','STATE','']}>{findings.map((f,i)=><tr id={i===0?'finding-critical':undefined} key={f[0]}><td><Status value={f[2]}/></td><td><b>{f[0]}</b><small className="cell-sub">Policy evaluation · demo</small></td><td className="mono">{f[1]}</td><td>{['Platform SRE','Commerce','Identity','Finance','Platform'][i]}</td><td className="mono">Jun {12-i}, 2025</td><td><Status value={f[3]}/></td><td><button className="button small-button" onClick={()=>showFindToast(f[1])}>Details</button></td></tr>)}</DataTable></Panel></>}
function showFindToast(name:string){const titles:Record<string,string>={'network-edge':'Public ingress rule permits broad CIDR','checkout-api':'Container image has outdated base layer','identity-gateway':'TLS certificate rotation due in 19 days','billing-worker':'S3 bucket logging configuration incomplete','event-stream':'IAM role has unused permission scope'};window.dispatchEvent(new CustomEvent('cloudops-security-detail',{detail:{id:`FND-${name}`,title:titles[name]??'Security finding',resource:name,description:'Illustrative finding from the local demo provider. No live security scan has run.',severity:name==='network-edge'?'Critical':'Medium',status:'Open',recommendation:['Confirm the resource and owner.','Apply the least-privilege or network restriction needed.','Record remediation evidence or an approved exception.']}}))}

function AuditPanel({rows,search,setSearch}:{rows:AuditEvent[];search:string;setSearch:(s:string)=>void}){const [category,setCategory]=useState('All activity');const list=rows.filter(x=>(category==='All activity'||x.category===category)&&(x.actor+x.action+x.resource+x.outcome).toLowerCase().includes(search.toLowerCase()));return <><Panel title="Audit events" detail="Local sample history · searchable and filterable"><div className="table-toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Search actor, action, resource…"/><label className="filter-select"><Filter size={13}/><select value={category} onChange={e=>setCategory(e.target.value)}>{['All activity','Release','Access','Incident','Configuration'].map(x=><option key={x}>{x}</option>)}</select><ChevronDown size={12}/></label><button className="button subtle"><Download size={14}/>Export</button></div><DataTable headers={['EVENT','ACTOR','ACTION','RESOURCE','CATEGORY','OUTCOME']}><>{list.slice(0,24).map(e=><tr key={e.id}><td className="mono accent-text">{e.id}<small className="cell-sub">{e.time}</small></td><td>{e.actor}</td><td>{e.action}</td><td className="mono">{e.resource}</td><td><span className="env-chip">{e.category}</span></td><td><Status value={e.outcome}/></td></tr>)}</></DataTable><Pagination count={list.length}/></Panel></>}
function Engineering({data,deployments}:{data:Metric[];deployments:Deployment[]}){return <><div className="stat-grid compact"><Stat label="Deployment frequency" value="3.8 / day" delta="↑ 12% over prior 30d" icon={GitBranch}/><Stat label="Lead time for changes" value="3h 42m" delta="↓ 18% over prior 30d" icon={Timer}/><Stat label="Change failure rate" value="5.6%" delta="Target below 8%" icon={AlertTriangle}/><Stat label="MTTR" value="24 min" delta="↓ 6m over prior 30d" icon={RefreshCw}/></div><div className="two-column"><Panel title="Delivery flow" detail="Weekly release frequency and failed changes"><div className="engineering-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{week:'W20',deployments:24,failures:2},{week:'W21',deployments:31,failures:1},{week:'W22',deployments:28,failures:2},{week:'W23',deployments:38,failures:2}]}><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="week" tick={{fontSize:10,fill:'var(--chart-label)'}} axisLine={false} tickLine={false}/><YAxis hide/><Tooltip/><Bar dataKey="deployments" fill="#4cb49b" radius={[4,4,0,0]}/><Bar dataKey="failures" fill="#d77770" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></Panel><Panel title="Team delivery health" detail="Signals rolled up from demo records"><div className="team-list">{[['Commerce','11 releases','96%','92'],['Platform','8 releases','100%','88'],['Payments','6 releases','83%','79'],['Discovery','5 releases','80%','74']].map(t=><div className="team-row" key={t[0]}><b>{t[0]}</b><span>{t[1]}</span><span>{t[2]} success</span><div className="team-score"><i style={{width:`${t[3]}%`}}/></div><b>{t[3]}</b></div>)}</div></Panel></div><Panel title="Latest release events" detail={`${deployments.length} local demo deployments`}>{deployments.slice(0,5).map(d=><div className="compact-release" key={d.id}><span className="mono">{d.id}</span><b>{d.service}</b><span>{d.environment}</span><Status value={d.status}/><span className="mono">{d.time}</span></div>)}</Panel></>}

function Reliability({services,metrics}:{services:Service[];metrics:Metric[]}){return <><div className="reliability-hero"><div><span className="eyebrow">PLATFORM AVAILABILITY · LAST 30 DAYS</span><h2>99.94<span>%</span></h2><p>Weighted service-level objective attainment</p></div><div className="reliability-overview"><div><b>14.2%</b><small>Platform error budget consumed</small><div className="budget-track"><i style={{width:'14.2%'}}/></div></div><Status value="Within target"/></div></div><div className="stat-grid compact"><Stat label="Services meeting SLO" value="08 / 10" delta="2 service objectives at risk" icon={ShieldCheck}/><Stat label="Budget remaining" value="85.8%" delta="15 days in current window" icon={Activity}/><Stat label="p95 latency" value={`${Math.round(metrics.at(-1)?.latency??318)} ms`} delta="Target < 500 ms" icon={Timer}/><Stat label="Availability SLI" value="99.96%" delta="Target 99.9%" icon={CheckCircle2}/></div><Panel title="Service objectives" detail="Rolling 30-day objective status"><DataTable headers={['SERVICE','SLO / SLA','AVAILABILITY SLI','ERROR BUDGET','BURN RATE','STATUS']}><>{services.map((s,i)=><tr key={s.id}><td><b>{s.name}</b><small className="cell-sub">{s.team}</small></td><td className="mono">{s.slo}%</td><td><span className="mono">{(99.99-i*.008).toFixed(3)}%</span><div className="tiny-progress"><i style={{width:`${Math.min(100,(99.99-i*.008))}%`}}/></div></td><td><div className="budget-cell"><span>{i===0?'71%':'12%'}</span><div className="budget-track"><i className={i===0?'budget-risk':''} style={{width:i===0?'71%':'12%'}}/></div></div></td><td className="mono">{i===0?'2.1×':'0.4×'}</td><td><Status value={i===0?'At risk':'Healthy'}/></td></tr>)}</></DataTable></Panel></>}

function Reports({go,showToast}:{go:(p:string)=>void;showToast:(m:string)=>void}){const reports=[['Weekly operations brief','Reliability, incident, and release summary','Updated 2 hours ago','/'],['Service health scorecard','SLO attainment by service and owning team','Updated today','/reliability'],['Release quality report','Deployment frequency and change failure rate','Updated today','/release-history'],['Cloud cost allocation','Monthly trend and budget utilization','Updated 4 hours ago','/cost'],['Security posture snapshot','Open findings by severity and resource owner','Updated yesterday','/security'],['Audit activity extract','Searchable actions and access decisions','Updated moments ago','/audit']];return <><div className="report-intro"><div className="report-icon"><FileText size={21}/></div><div><h2>Operational reporting</h2><p>Focused reports for engineering reviews and on-call handoffs. Data shown is local demo content.</p></div><button className="button primary" onClick={()=>showToast('Report export prepared from local demo records')}><Download size={14}/>Export report</button></div><div className="report-grid">{reports.map((r,i)=><button className="panel report-card" key={r[0]} onClick={()=>go(r[3])}><div className="report-card-head"><span className={`report-glyph rg${i}`}><FileText size={16}/></span><MoreHorizontal size={15}/></div><h3>{r[0]}</h3><p>{r[1]}</p><div className="report-card-foot"><span>{r[2]}</span><ArrowRight size={14}/></div></button>)}</div></>}

function ServiceDetail({name,services,open,go}:{name:string;services:Service[];open:(x:unknown)=>void;go:(p:string)=>void}){const s=services.find(x=>x.name===name)||services[0];if(!s)return <EmptyState title="Service not found" detail="Choose a service from the catalog to view its profile."/>;return <><button className="back-link" onClick={()=>go('/services')}><ChevronLeft size={14}/>Back to catalog</button><div className="service-detail-hero"><div className="service-detail-icon"><Boxes size={22}/></div><div><span className="eyebrow">{s.team} · {s.tier}</span><h2 className="display">{s.name}</h2><p>{s.description}</p></div><Status value={s.health}/></div><div className="stat-grid compact"><Stat label="Availability objective" value={`${s.slo}%`} delta="Rolling 30-day SLO" icon={ShieldCheck}/><Stat label="Current version" value={s.version} delta="Production · us-east-1" icon={Package}/><Stat label="Service owner" value={s.owner} delta={`${s.team} team`} icon={Settings2}/><Stat label="Dependencies" value={String(s.dependencies.length).padStart(2,'0')} delta="Mapped relationships" icon={Network}/></div><div className="two-column"><Panel title="Service dependencies" detail="Upstream runtime relationships"><div className="dependency-detail-list">{s.dependencies.map((d,i)=><button key={d} onClick={()=>open(services.find(x=>x.name===d)||{name:d})}><span className={`health-mark ${i===0?'healthy':'degraded'}`}><Network size={14}/></span><b>{d}</b><span>Upstream</span><ArrowRight size={13}/></button>)}</div></Panel><Panel title="Operational ownership" detail="On-call and service metadata"><div className="owner-meta"><div><small>PRIMARY OWNER</small><b>{s.owner}</b></div><div><small>OWNING TEAM</small><b>{s.team}</b></div><div><small>CRITICALITY</small><b>{s.tier}</b></div><div><small>REGION</small><b className="mono">{s.region}</b></div><button className="button subtle" onClick={()=>open(s)}>View complete profile <ExternalLink size={13}/></button></div></Panel></div><Panel title="Recent service events" detail="Local demonstration records"><div className="compact-release"><span className="mono">REL-1048</span><b>Release promoted to production</b><span>Today</span><Status value="Succeeded"/><span className="mono">6m 12s</span></div><div className="compact-release"><span className="mono">INC-8421</span><b>Latency objective alert</b><span>Today</span><Status value="Investigating"/><span className="mono">14:36 UTC</span></div></Panel></>}

function Pagination({count}:{count:number}){const [page,setPage]=useState(1);const pages=Math.max(1,Math.ceil(count/10));return <div className="pagination"><span>Showing <b>{Math.min(count,10)}</b> of <b>{count}</b> records</span><div><button aria-label="Previous page" disabled={page===1} onClick={()=>setPage(Math.max(1,page-1))}><ChevronLeft size={14}/></button><span>Page {page} of {pages}</span><button aria-label="Next page" disabled={page>=pages} onClick={()=>setPage(Math.min(pages,page+1))}><ChevronRight size={14}/></button></div></div>}
function EmptyState({title,detail}:{title:string;detail:string}){return <div className="empty-state"><div><Search size={18}/></div><b>{title}</b><p>{detail}</p></div>}

function CommandPalette({close,go,data,openRecord,setEnvironment,createIncident}:{close:()=>void;go:(p:string)=>void;data:Data|null;openRecord:(x:unknown)=>void;setEnvironment:(s:string)=>void;createIncident:()=>void}){
  const [query,setQuery]=useState('');
  const q=query.toLowerCase();
  const pages=navGroups.flatMap(g=>g.items.map(([path,label,Icon])=>({path,label,Icon,group:g.label}))).filter(x=>(x.label+x.group).toLowerCase().includes(q)).slice(0,8);
  const records=data?[
    ...data.services.map(item=>({key:`service-${item.id}`,kind:'SERVICE',label:item.name,detail:`${item.team} · ${item.environment} · ${item.health}`,path:`/service/${item.name}`,item,search:`${item.name} ${item.team} ${item.owner} ${item.environment}`})),
    ...data.deployments.map(item=>({key:`deployment-${item.id}`,kind:'DEPLOYMENT',label:`${item.id} · ${item.service}`,detail:`${item.environment} · ${item.status} · ${item.version}`,path:'/deployments',item,search:`${item.id} ${item.service} ${item.environment} ${item.status}`})),
    ...data.incidents.map(item=>({key:`incident-${item.id}`,kind:'INCIDENT',label:`${item.id} · ${item.title}`,detail:`${item.severity} · ${item.service} · ${item.status}`,path:'/incidents',item,search:`${item.id} ${item.title} ${item.service} ${item.environment}`})),
    ...data.alerts.map(item=>({key:`alert-${item.id}`,kind:'ALERT',label:`${item.id} · ${item.title}`,detail:`${item.severity} · ${item.service} · ${item.status}`,path:'/alerts',item,search:`${item.id} ${item.title} ${item.service} ${item.status}`})),
    ...data.servers.map(item=>({key:`server-${item.id}`,kind:'SERVER',label:item.name,detail:`${item.environment} · ${item.region} · ${item.status}`,path:'/servers',item,search:`${item.id} ${item.name} ${item.service} ${item.environment}`})),
    ...data.changes.map(item=>({key:`change-${item.id}`,kind:'CHANGE',label:`${item.id} · ${item.title}`,detail:`${item.environment} · ${item.risk} risk · ${item.status}`,path:'/changes',item,search:`${item.id} ${item.title} ${item.service} ${item.requester}`})),
    ...data.runbooks.map(item=>({key:`runbook-${item.id}`,kind:'RUNBOOK',label:item.title,detail:`${item.id} · ${item.category} · ${item.owner}`,path:'/runbooks',item,search:`${item.id} ${item.title} ${item.category} ${item.owner}`})),
    ...data.logs.map(item=>({key:`log-${item.id}`,kind:'LOG',label:`${item.level} · ${item.service}`,detail:`${item.time} · ${item.message}`,path:'/logs',item,search:`${item.id} ${item.level} ${item.service} ${item.message} ${item.traceId} ${item.requestId}`})),
    ...data.traces.map(item=>({key:`trace-${item.id}`,kind:'TRACE',label:`${item.service} · ${item.route}`,detail:`${item.id} · ${item.duration} ms · ${item.status}`,path:'/traces',item,search:`${item.id} ${item.service} ${item.route} ${item.status}`})),
    ...data.costs.map(item=>({key:`cost-${item.id}`,kind:'COST',label:`${item.service} · ${item.category}`,detail:`${money(item.current)} · ${item.environment}`,path:'/cost',item,search:`${item.id} ${item.service} ${item.category} ${item.environment}`})),
    ...data.auditEvents.map(item=>({key:`audit-${item.id}`,kind:'AUDIT',label:`${item.actor} · ${item.action}`,detail:`${item.resource} · ${item.time}`,path:'/audit',item,search:`${item.id} ${item.actor} ${item.action} ${item.resource}`})),
  ].filter(x=>(x.label+' '+x.detail+' '+x.search).toLowerCase().includes(q)).slice(0,12):[];
  const selectRecord=(record:typeof records[number])=>{go(record.path);close();openRecord(record.item)};
  const actions=[
    {label:'Create incident',detail:'Open the local incident workflow',icon:AlertOctagon,onSelect:()=>{createIncident();close()}},
    ...(['QA','UAT','PRODUCTION'] as const).map(environment=>({label:`View ${environment}`,detail:'Switch environment and open the command center',icon:Globe2,onSelect:()=>{setEnvironment(environment);go('/');close()}})),
    {label:'Search logs',detail:'Open the log explorer',icon:ScrollText,onSelect:()=>{go('/logs');close()}},
  ];
  return <div className="modal-scrim palette-scrim" onClick={close}><div className="command-modal" onClick={e=>e.stopPropagation()}><div className="command-input"><Search size={17}/><input autoFocus aria-label="Search all CloudOps records" placeholder="Search services, deployments, incidents, logs…" value={query} onChange={e=>setQuery(e.target.value)}/><kbd>ESC</kbd></div><div className="command-results">{!q&&<div className="command-section-label">QUICK ACTIONS</div>}{!q&&actions.map(action=><button key={action.label} onClick={action.onSelect}><action.icon size={15}/><span>{action.label}</span><small>{action.detail}</small><ArrowRight size={13}/></button>)}{pages.length>0&&<div className="command-section-label">PAGES</div>}{pages.map(p=><button key={p.path} onClick={()=>{go(p.path);close()}}><p.Icon size={15}/><span>{p.label}</span><small>{p.group}</small><ArrowRight size={13}/></button>)}{records.length>0&&<div className="command-section-label">RECORDS</div>}{records.map(record=><button key={record.key} onClick={()=>selectRecord(record)}><Search size={15}/><span>{record.label}</span><small>{record.kind} · {record.detail}</small><ArrowRight size={13}/></button>)}{q&&!pages.length&&!records.length&&<EmptyState title="No matching results" detail="Search for any page or demo record by name, ID, service, or status."/>}</div><div className="command-foot"><span>Search across pages and demo records</span><span>ESC to close</span></div></div></div>
}

function DetailDrawer({item,close,go,toast}:{item:unknown;close:()=>void;go:(p:string)=>void;toast:(m:string)=>void}){const obj=item as Record<string,unknown>;const title=String(obj.title??obj.name??obj.service??obj.id??'Record details');const entries=Object.entries(obj).filter(([k])=>k!=='steps'&&k!=='spans'&&k!=='dependencies');return <div className="drawer-scrim" onClick={close}><aside className="detail-drawer" onClick={e=>e.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">RECORD DETAIL · DEMO</span><h2>{title}</h2></div><button className="icon-button" aria-label="Close details" onClick={close}><X size={17}/></button></div><div className="drawer-content">{entries.map(([key,value])=><div className="detail-field" key={key}><small>{key.replace(/[A-Z]/g,m=>` ${m}`).toUpperCase()}</small><b>{typeof value==='object'?JSON.stringify(value):String(value)}</b></div>)}{Array.isArray(obj.steps)&&<div className="drawer-section"><h3>Response steps</h3>{(obj.steps as string[]).map((s,i)=><div className="drawer-step" key={s}><span>{String(i+1).padStart(2,'0')}</span>{s}</div>)}</div>}{Array.isArray(obj.spans)&&<div className="drawer-section"><h3>Trace spans</h3>{(obj.spans as Trace['spans']).map(s=><div className="span-line" key={s.name}><span>{s.service}</span><b>{s.name}</b><span className="mono">{s.duration} ms</span></div>)}</div>}{Array.isArray(obj.dependencies)&&<div className="drawer-section"><h3>Service dependencies</h3>{(obj.dependencies as string[]).map(d=><button className="dependency-drawer-link" key={d} onClick={()=>{close();go(`/service/${d}`)}}><Network size={14}/>{d}<ArrowRight size={13}/></button>)}</div>}<div className="drawer-note"><span className="pulse-dot"/>This is a locally simulated record. No external service is connected.</div></div><div className="drawer-actions"><button className="button subtle" onClick={()=>{navigator.clipboard?.writeText(JSON.stringify(obj,null,2));toast('Record copied to clipboard')}}><FileText size={14}/>Copy record</button><button className="button primary" onClick={close}>Done</button></div></aside></div>}

function CreateDialog({path,close,create}:{path:string;close:()=>void;create:(kind:string,title:string,service:string,details:string)=>void}){const label=path==='/incidents'?'incident':path==='/changes'?'change request':path==='/services'?'service':'action';const [title,setTitle]=useState('');const [service,setService]=useState('checkout-api');const [details,setDetails]=useState('');return <div className="modal-scrim" onClick={close}><div className="create-modal" onClick={e=>e.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">LOCAL DEMO WORKFLOW</span><h2>Create {label}</h2></div><button className="icon-button" aria-label="Close dialog" onClick={close}><X size={17}/></button></div><form onSubmit={e=>{e.preventDefault();create(label,title,service,details)}}><label className="form-label">{label==='service'?'Service name':'Title'}<input required autoFocus value={title} onChange={e=>setTitle(e.target.value)} placeholder="Short, actionable summary"/></label><label className="form-label">{label==='service'?'Owning service / team':'Service'}<select value={service} onChange={e=>setService(e.target.value)}>{['checkout-api','payments-ledger','identity-gateway','inventory-core','catalog-api','fraud-engine'].map(s=><option key={s}>{s}</option>)}</select></label><label className="form-label">Context<textarea value={details} onChange={e=>setDetails(e.target.value)} placeholder="Customer impact, scope, or change summary" rows={4}/></label><div className="form-footnote"><AlertTriangle size={14}/>Creates a local demo record only. No infrastructure action will run.</div><div className="dialog-actions"><button className="button subtle" type="button" onClick={close}>Cancel</button><button className="button primary" type="submit"><Plus size={14}/>Create {label}</button></div></form></div></div>}

function App() {
  return <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><CommandCenter/></WouterRouter>;
}

export default App;